insert into app.creators (id, slug, display_name, studio_name, city, bio, accent_hue, emoji, created_at) values
  ('seed_sarah', 'clay-and-ember', 'Sarah Thomas', 'Clay & Ember Studio', 'Bengaluru', 'Wheel-thrown stoneware made in small batches in a home studio. Every glaze is mixed by hand.', 18, '☕', '2026-07-10T07:02:01.671Z'),
  ('seed_kabir', 'neel-blue-pottery', 'Kabir Rathore', 'Neel Blue Pottery', 'Jaipur', 'Third-generation Jaipur blue pottery — quartz clay, cobalt and hand-painted florals.', 215, '🏺', '2026-08-09T07:02:01.671Z');
insert into app.batches (id, code, creator_id, title, tagline, description, unit_label, price, funding_goal, max_quantity, funding_deadline, cover_hue, stage, stage_history, created_at) values
  ('autumn-forest', 'AF', 'seed_sarah', 'The Autumn Forest Mug Series', 'Speckled stoneware in moss, rust and bark tones.', 'Fifty wheel-thrown mugs inspired by October walks through the Nilgiri forests. Each one is dipped in a layered glaze that pools into deep rust at the rim and fades to moss green at the base. Holds 350 ml, dishwasher safe, and no two are the same.', 'mugs', 1800, 30, 50, '2026-10-20T07:02:01.671Z', 22, 'funding', '[{"stage":"funding","at":"2026-09-29T07:02:01.671Z","note":"Pre-orders are open!"}]'::jsonb, '2026-09-29T07:02:01.671Z'),
  ('midnight-tide', 'MT', 'seed_sarah', 'Midnight Tide Tumblers', 'Deep cobalt tumblers with a ripple-carved base.', 'Hand-carved ripples run around the base of every tumbler, glazed in a cobalt blue that breaks to white on the ridges. Sized for cold brew or a long nimbu pani.', 'tumblers', 2200, 20, 40, '2026-09-28T07:02:01.671Z', 215, 'kiln', '[{"stage":"funding","at":"2026-09-08T07:02:01.671Z","note":"Pre-orders are open!"},{"stage":"mold","at":"2026-10-02T07:02:01.671Z","note":"We hit 32 pre-orders! 🎉 All 32 tumblers were thrown this morning and are drying on the shelves."},{"stage":"kiln","at":"2026-10-06T19:02:01.671Z","note":"Your tumblers are currently baking at 1,200°C! Kiln opens Thursday."}]'::jsonb, '2026-09-08T07:02:01.671Z'),
  ('sunrise-bowls', 'SB', 'seed_sarah', 'Sunrise Ramen Bowls', 'Generous bowls with a saffron-to-blush gradient.', 'Big, deep bowls for ramen, khichdi and everything in between. The glaze is sprayed by hand to fade from saffron at the rim to a soft blush inside.', 'bowls', 2600, 15, 30, '2026-08-29T07:02:01.671Z', 38, 'fulfillment', '[{"stage":"funding","at":"2026-08-09T07:02:01.671Z","note":"Pre-orders are open!"},{"stage":"mold","at":"2026-09-08T07:02:01.671Z","note":""},{"stage":"kiln","at":"2026-09-18T07:02:01.671Z","note":""},{"stage":"glazing","at":"2026-09-26T07:02:01.671Z","note":""},{"stage":"fulfillment","at":"2026-10-05T07:02:01.671Z","note":"Every bowl survived the kiln! Packing starts today, a few postal zones at a time."}]'::jsonb, '2026-08-09T07:02:01.671Z'),
  ('indigo-garden', 'IG', 'seed_kabir', 'Indigo Garden Dinner Plates', 'Hand-painted cobalt florals on quartz clay.', 'Twenty-four dinner plates in traditional Jaipur blue pottery. Each one is hand-painted with a different garden motif and fired at low temperature for that glassy finish.', 'plates', 2400, 20, 24, '2026-10-26T07:02:01.671Z', 220, 'funding', '[{"stage":"funding","at":"2026-10-04T07:02:01.671Z","note":"Pre-orders are open — only 24 will ever be made!"}]'::jsonb, '2026-10-04T07:02:01.671Z');
