  ('c-seed-1', 'midnight-tide', 'kiln:2026-10-06T19:02:01.671Z', null, '{"role":"buyer","name":"Aarav Mehta","orderId":"midnight-tide-o2","orderNumber":"MT-002"}'::jsonb, 'Is it nerve-wracking opening the kiln? 😄 Can’t wait to see the blue!', '2026-10-07T01:02:01.671Z'),
  ('c-seed-3', 'midnight-tide', 'kiln:2026-10-06T19:02:01.671Z', null, '{"role":"buyer","name":"Ananya Iyer","orderId":"midnight-tide-o5","orderNumber":"MT-005"}'::jsonb, 'Will the ripple base be glazed too, or left raw?', '2026-10-07T11:02:01.671Z'),
