  ('c-seed-6', 'sunrise-bowls', 'fulfillment:2026-10-05T07:02:01.671Z', null, '{"role":"buyer","name":"Zara Khan","orderId":"sunrise-bowls-o3","orderNumber":"SB-003"}'::jsonb, 'Mine says awaiting pickup — any idea when the courier comes?', '2026-10-07T21:02:01.671Z'),
  ('c-seed-8', 'autumn-forest', 'funding:2026-09-29T07:02:01.671Z', null, '{"role":"buyer","name":"Tara Menon","orderId":"autumn-forest-o1","orderNumber":"AF-001"}'::jsonb, 'Shared this with my book club — hope we hit 30! 🍂', '2026-10-06T05:02:01.671Z'),
